mapper.delete:
WITH expired AS (
    SELECT id FROM operation_log WHERE tenant_id = #{tenantId} AND created_at < #{cutoff}
    ORDER BY created_at, id LIMIT 500 FOR UPDATE
) DELETE FROM operation_log WHERE tenant_id = #{tenantId} AND id IN (SELECT id FROM expired)

WITH expired AS (
    SELECT id FROM permission_change_log WHERE tenant_id = #{tenantId} AND created_at < #{cutoff}
    ORDER BY created_at, id LIMIT 500 FOR UPDATE
) DELETE FROM permission_change_log WHERE tenant_id = #{tenantId} AND id IN (SELECT id FROM expired)

WITH expired AS (
    SELECT id FROM sys_login_log WHERE tenant_id = #{tenantId} AND login_at < #{cutoff}
    ORDER BY login_at, id LIMIT 500 FOR UPDATE
) DELETE FROM sys_login_log WHERE tenant_id = #{tenantId} AND id IN (SELECT id FROM expired)
